def validate(clock):
    if not isinstance(clock, dict) or any(not isinstance(v, int) or v < 0 for v in clock.values()):
        raise ValueError("invalid vector clock")
    return dict(clock)

def compare(left, right):
    left, right = validate(left), validate(right)
    all_keys = set(left) | set(right)
    left_ge = all(left.get(k, 0) >= right.get(k, 0) for k in all_keys)
    right_ge = all(right.get(k, 0) >= left.get(k, 0) for k in all_keys)
    if left_ge and not right_ge:
        return 1
    if right_ge and not left_ge:
        return -1
    return 0

def joined(clocks):
    result = {}
    for clock in clocks:
        for k, v in validate(clock).items():
            result[k] = max(result.get(k, 0), v)
    return dict(sorted(result.items()))

