    left_ge = all(left.get(k, 0) >= right.get(k, 0) for k in all_keys)
    right_ge = all(right.get(k, 0) >= left.get(k, 0) for k in all_keys)
    if left_ge and not right_ge:
        return 1
    if right_ge and not left_ge:
        return -1
    return 0

