import json
from clocks import compare, validate, joined

def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"))

def normalize(record):
    return {
        "key": record["key"],
        "node": record["node"],
        "clock": validate(record.get("clock", {})),
        "value": record.get("value"),
        "deleted": bool(record.get("deleted", False)),
    }

def resolve(records):
    # deduplicate exact records
    unique = {}
    for r in records:
        rec = normalize(r)
        unique[canonical(rec)] = rec
    versions = list(unique.values())
    # compute frontier: strictly maximal clocks
    frontier = []
    for v in versions:
        dominated = False
        for other in versions:
            if other is v:
                continue
            if compare(other["clock"], v["clock"]) >= 0:
                dominated = True
                break
        if not dominated:
            frontier.append(v)
    # conflict if more than one frontier
    conflict = len(frontier) > 1
    # choose winner: tombstone wins, then lexicographically greatest node, then lexicographically greatest canonical value
    def winner_key(row):
        return (
            not row["deleted"],  # tombstone (deleted) preferred
            row["node"],
            canonical(row["value"]),
        )
    winner = max(frontier, key=winner_key)
    return {
        "key": winner["key"],
        "value": None if winner["deleted"] else winner["value"],
        "deleted": winner["deleted"],
        "clock": joined([v["clock"] for v in versions]),
        "winner": winner["node"],
        "conflict": conflict,
    }

