def validate(clock):
    if not isinstance(clock, dict) or any(not isinstance(v, int) or v < 0 for v in clock.values()):
        raise ValueError("invalid vector clock")
    return dict(clock)

def compare(left, right):
    left, right = validate(left), validate(right)
    all_keys = set(left) | set(right)
    left_greater = False
    right_greater = False
    for k in all_keys:
        lv = left.get(k, 0)
        rv = right.get(k, 0)
        if lv > rv:
            left_greater = True
        elif rv > lv:
            right_greater = True
    if left_greater and not right_greater:
        return 1
    if right_greater and not left_greater:
        return -1
    return 0

def joined(clocks):
    result = {}
    for clock in clocks:
        for k, v in validate(clock).items():
            result[k] = max(result.get(k, 0), v)
    return dict(sorted(result.items()))

