import re

def tokens(text):
    # Convert text to lowercase ASCII before extracting alphanumeric tokens
    # This ensures that uppercase letters are treated the same as lowercase
    # and that only letters a-z and digits 0-9 are tokenized.
    lowered = text.lower()
    return re.findall(r"[a-z0-9]+", lowered)

def index(documents):
    result, seen = [], set()
    for document in documents:
        if document["id"] in seen:
            raise ValueError("duplicate document id")
        seen.add(document["id"])
        counts = {}
        for token in tokens(document["title"] + " " + document["body"]):
            counts[token] = counts.get(token, 0) + 1
        result.append((document, counts))
    return result

