def classify(graph, sequence, statuses):
    """Classify nodes into ready, blocked, running, done, failed.

    - statuses may contain explicit states for a subset of nodes.
    - Missing nodes are considered pending.
    - A node is ready if it is pending, not blocked, and all its direct dependencies are done.
    - Blocked nodes are those (transitively) depending on a failed node and not themselves failed.
    - Nodes with explicit running/done/failed keep that status.
    """
    # Validate input
    if any(node not in graph for node in statuses):
        raise ValueError("unknown status node")
    if any(status not in ("pending", "running", "done", "failed") for status in statuses.values()):
        raise ValueError("unknown status")

