def _transitive_blocked(graph, failed):
    """Return the set of nodes that are blocked because they (directly or indirectly)
    depend on any node in *failed*.
    """
    blocked = set()
    # Perform a reverse traversal: for each failed node, find nodes that need it
    # Build reverse adjacency list
    rev = {n: [] for n in graph}
    for node, deps in graph.items():
        for d in deps:
            rev[d].append(node)
    stack = list(failed)
    while stack:
        cur = stack.pop()
        for dependent in rev.get(cur, []):
            if dependent not in blocked and dependent not in failed:
                blocked.add(dependent)
                stack.append(dependent)
    return blocked


def classify(graph, sequence, statuses):
    # Validate input
    if any(node not in graph for node in statuses):
        raise ValueError("unknown status node")
    if any(status not in ("pending", "running", "done", "failed") for status in statuses.values()):
        raise ValueError("unknown status")

    failed = {node for node, status in statuses.items() if status == "failed"}
    blocked = _transitive_blocked(graph, failed)

    result = {"ready": [], "blocked": [], "running": [], "done": [], "failed": []}
    for node in sequence:
        status = statuses.get(node, "pending")
        if status == "running":
            result["running"].append(node)
        elif status == "done":
            result["done"].append(node)
        elif status == "failed":
            result["failed"].append(node)
        elif node in blocked:
            result["blocked"].append(node)
        else:
            # pending node not blocked: check if all dependencies are done
            deps = graph[node]
            if all(statuses.get(dep, "pending") == "done" for dep in deps):
                result["ready"].append(node)
            # otherwise it stays omitted (still pending but not ready)
    return result

