    left, right = validate(left), validate(right)
    keys = set(left) | set(right)
    left_greater = False
    right_greater = False
    for key in keys:
        l = left.get(key, 0)
        r = right.get(key, 0)
        if l > r:
            left_greater = True
        elif r > l:
            right_greater = True
    if left_greater and not right_greater:
