import json
from clocks import compare, validate, joined

def canonical(value):
    """Return a deterministic JSON string for a value, with sorted keys and compact separators."""
    return json.dumps(value, sort_keys=True, separators=(",", ":"))

def normalize(record):
    """Normalize a raw record into a canonical internal representation.
    Ensures the clock is validated, deleted is a boolean, and value may be omitted.
    """
    return {
        "key": record["key"],
        "node": record["node"],
        "clock": validate(record["clock"]),
        "value": record.get("value"),
        "deleted": bool(record.get("deleted", False)),
    }

def resolve(records):
    """Resolve a list of records for a single key.
    Returns the merged result according to the specification.
    """
    # Deduplicate exact canonical records
    unique = {}
    for row in records:
        rec = normalize(row)
        unique[canonical(rec)] = rec
    versions = list(unique.values())

    # Determine the causal frontier: versions not strictly dominated by any other
    frontier = []
    for cand in versions:
        dominated = False
        for other in versions:
            if other is cand:
                continue
            # other dominates cand if compare(other, cand) == 1
            if compare(other["clock"], cand["clock"]) == 1:
                dominated = True
                break
        if not dominated:
            frontier.append(cand)

    # Choose winner among frontier according to tie‑break rules:
    # 1. Prefer tombstone (deleted=True)
    # 2. Lexicographically greatest node
    # 3. Lexicographically greatest canonical JSON value
    def winner_key(row):
        return (row["deleted"], row["node"], canonical(row["value"]))

    winner = max(frontier, key=winner_key)

    # Build merged result
    merged_clock = joined([v["clock"] for v in versions])
    return {
        "key": winner["key"],
        "value": None if winner["deleted"] else winner["value"],
        "deleted": winner["deleted"],
        "clock": merged_clock,
        "winner": winner["node"],
        "conflict": len(frontier) > 1,
    }

