def validate(clock):
    if not isinstance(clock, dict):
        raise ValueError("invalid vector clock")
    for key, value in clock.items():
        if not isinstance(value, int) or isinstance(value, bool) or value < 0:
            raise ValueError("invalid vector clock")
    return dict(clock)

def compare(left, right):
    left, right = validate(left), validate(right)
    keys = set(left) | set(right)
    left_ge = all(left.get(k, 0) >= right.get(k, 0) for k in keys)
    right_ge = all(right.get(k, 0) >= left.get(k, 0) for k in keys)
    if left_ge and not right_ge:
        return 1
    if right_ge and not left_ge:
        return -1
    return 0

def joined(clocks):
    result = {}
    for clock in clocks:
        for key, value in validate(clock).items():
            result[key] = max(result.get(key, 0), value)
    # include keys that may have zero in all clocks
    all_keys = set(result.keys())
    for clock in clocks:
        all_keys.update(clock.keys())
    for key in all_keys:
        result.setdefault(key, 0)
    return dict(sorted(result.items()))

