def validate(clock):
    """Validate that a vector clock is a dict of non‑negative integers.
    Booleans are explicitly rejected because they are subclasses of ``int``
    but are not valid counter values in this domain.
    """
    if not isinstance(clock, dict):
        raise ValueError("invalid vector clock")
    for key, value in clock.items():
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValueError("invalid vector clock")
    return dict(clock)

def compare(left, right):
    """Compare two clocks.
    Returns 1 if *left* strictly dominates *right*, -1 if *right* strictly
    dominates *left*, and 0 otherwise (equal or concurrent).
    """
    left, right = validate(left), validate(right)
    keys = set(left) | set(right)
    greater = any(left.get(k, 0) > right.get(k, 0) for k in keys)
    smaller = any(left.get(k, 0) < right.get(k, 0) for k in keys)
    if greater and not smaller:
        return 1
    if smaller and not greater:
        return -1
    return 0

def joined(clocks):
    """Component‑wise maximum of a collection of clocks.
    Explicit zero components are retained because they appear in the input
    dictionaries.
    """
    result = {}
    for clock in clocks:
        for key, value in validate(clock).items():
            result[key] = max(result.get(key, 0), value)
    return dict(sorted(result.items()))

