from indexing import tokens

def ranked(indexed, query, mode, labels):
    """Rank documents based on a lexical query.

    * ``mode`` – "all" (default) requires every unique query term to be present;
      "any" requires at least one.
    * ``labels`` – a list of labels that must all be present in the document.
    * Returns a list of dicts with ``id``, ``title`` and ``score`` sorted by
      descending score then ascending id.
    """
    if mode not in ("all", "any"):
        raise ValueError("unknown query mode")
    # normalize and deduplicate query terms
    terms = list(dict.fromkeys(tokens(query)))
    if not terms:
        return []
    result = []
    for doc, counts in indexed:
        # label filtering: all supplied labels must be present
        doc_labels = set(doc.get("labels", []))
        if labels and not set(labels).issubset(doc_labels):
            continue
        # determine which terms are present
        hits = [term in counts for term in terms]
        if (mode == "all" and all(hits)) or (mode == "any" and any(hits)):
            score = sum(counts.get(term, 0) for term in terms)
            result.append({"id": doc["id"], "title": doc["title"], "score": score})
    # sort: descending score, then ascending id (lexicographically)
    result.sort(key=lambda row: (-row["score"], row["id"]))
    return result

def facets(indexed):
    """Return a mapping of label -> document count.

    Each document contributes at most one count per distinct label, even if the
    label appears multiple times in the document's label list.
    """
    label_counts = {}
    for doc, _ in indexed:
        seen = set()
        for label in doc.get("labels", []):
            if label not in seen:
                label_counts[label] = label_counts.get(label, 0) + 1
                seen.add(label)
    # return a dict sorted by label for deterministic output
    return dict(sorted(label_counts.items()))

