def _match_labels(doc_labels, required_labels):
    """Return True if *required_labels* is a subset of *doc_labels*.
    """
    if not required_labels:
        return True
    return all(label in doc_labels for label in required_labels)

def ranked(indexed, query, mode, labels):
    if mode not in ("all", "any"):
        raise ValueError("unknown query mode")
    terms = set(tokens(query))
    if not terms:
        return []
    results = []
    for doc, counts in indexed:
        doc_labels = doc.get("labels", [])
        if not _match_labels(doc_labels, labels):
            continue
        hits = [term in counts for term in terms]
        if (mode == "all" and all(hits)) or (mode == "any" and any(hits)):
            score = sum(counts.get(term, 0) for term in terms)
            results.append({"id": doc["id"], "title": doc["title"], "score": score})
    # Sort by descending score, then ascending id
    results.sort(key=lambda r: (-r["score"], r["id"]))
    return results

def facets(indexed):
    label_counts = {}
    for doc, _ in indexed:
        seen_labels = set()
        for label in doc.get("labels", []):
            if label not in seen_labels:
                label_counts[label] = label_counts.get(label, 0) + 1
                seen_labels.add(label)
    return dict(sorted(label_counts.items()))
