def order(graph):
    """Return a topological ordering of the graph.

    The ordering picks the lexicographically smallest node that is ready at each step.
    If a cycle is detected, a ValueError is raised.
    """
    # Kahn's algorithm with lexicographic tie‑breaker
    # Compute in‑degree counts
    indegree = {node: 0 for node in graph}
    for deps in graph.values():
        for dep in deps:
            indegree[dep] += 1

    # Initialise the set of nodes with zero indegree
    zero = sorted([n for n, d in indegree.items() if d == 0])
    result = []
    while zero:
        # Pick the smallest available node
        node = zero.pop(0)
        result.append(node)
        # Decrease indegree of its dependents
        for dependent, deps in graph.items():
            if node in deps:
                indegree[dependent] -= 1
                if indegree[dependent] == 0:
                    # Keep zero sorted for lexicographic order
                    # Insert while maintaining order
                    import bisect
                    bisect.insort(zero, dependent)
    if len(result) != len(graph):
        # Cycle detected
        raise ValueError("cycle detected")
    return result
