def blocked(graph, failed):
    """Return the set of nodes that are blocked due to transitive failures.
    Any node that (directly or indirectly) depends on a failed node is blocked,
    excluding the failed nodes themselves.
    """
    blocked_set = set()
    # Perform a simple propagation: if a node depends on a blocked or failed node, it becomes blocked.
    changed = True
    while changed:
        changed = False
        for node, needs in graph.items():
            if node in failed or node in blocked_set:
                continue
            if any(dep in failed or dep in blocked_set for dep in needs):
                blocked_set.add(node)
                changed = True
    return blocked_set

def classify(graph, sequence, statuses):
    """Classify nodes into ready, blocked, running, done, and failed.
    - "pending" nodes are those not present in statuses.
    - A node is ready if it is pending and all its direct dependencies are done.
    - Blocked nodes are pending nodes that have any (direct or transitive) dependency that failed.
    - Explicit statuses (running, done, failed) take precedence.
    The returned lists follow the provided topological ``sequence`` order.
    """
    if any(node not in graph for node in statuses):
        raise ValueError("unknown status node")
    if any(status not in ("pending", "running", "done", "failed") for status in statuses.values()):
        raise ValueError("unknown status")

    failed = {node for node, status in statuses.items() if status == "failed"}
    unavailable = blocked(graph, failed)
    result = {"ready": [], "blocked": [], "running": [], "done": [], "failed": []}

    for node in sequence:
        status = statuses.get(node, "pending")
        if status in ("running", "done", "failed"):
            result[status].append(node)
        elif node in unavailable:
            result["blocked"].append(node)
        else:
            # pending node with all dependencies done -> ready
            if all(statuses.get(dep, "pending") == "done" for dep in graph[node]):
                result["ready"].append(node)
    return result

