def amount(value):
    if not isinstance(value, int) or value < 0:
        raise ValueError("money must be nonnegative integer cents")
    return value

def round_half_up(value, numerator, denominator):
    # Half‑up rounding: add half of denominator before integer division
    return (value * numerator + denominator // 2) // denominator

def discount(subtotal, coupons):
    seen = set()
    total_discount = 0
    for coupon in coupons:
        code = coupon["code"]
        if code in seen:
            continue
        seen.add(code)
        cents = amount(coupon["cents"])
        total_discount += cents
    return min(subtotal, total_discount)

