def amount(value):
    if type(value) is not int or value < 0:
        raise ValueError("money must be nonnegative integer cents")
    return value

def round_ratio(value, numerator, denominator):
    # Perform half-up rounding of (value * numerator) / denominator using integer arithmetic.
    # Multiply by 2 to handle the half case, then add denominator to round up when exactly half.
    # This avoids floating point inaccuracies.
    return (value * numerator * 2 + denominator) // (2 * denominator)

def discount(subtotal, coupons):
    seen = set()
    result = 0
    for coupon in coupons:
        code = coupon["code"]
        if code in seen:
            continue
        seen.add(code)
        result += amount(coupon["cents"])
    return min(subtotal, result)

