def quantity(value):
    if type(value) is not int or value < 0:
        raise ValueError("quantity must be a nonnegative integer")
    return value

def replay(initial, events):
    stock = {sku: quantity(value) for sku, value in initial.items()}
    seen = set()
    for event in events:
        identifier = event["id"]
        if identifier in seen:
            # duplicate event, ignore per idempotency rule
            continue
        seen.add(identifier)
        count = quantity(event["quantity"])
        sku = event["sku"]
        kind = event["kind"]
        if kind not in ("receive", "ship"):
            raise ValueError("unknown event")
        delta = count if kind == "receive" else -count
        updated = stock.get(sku, 0) + delta
        if updated < 0:
            raise ValueError("negative stock")
        stock[sku] = updated
    return stock

