def matches(pattern, resource):
    """Return True if the pattern matches the resource.
    Patterns and resources are '/' separated. '*' matches exactly one segment.
    The number of segments must be equal.
    """
    pat_parts = pattern.split('/')
    res_parts = resource.split('/')
    if len(pat_parts) != len(res_parts):
        return False
    return all(p == '*' or p == r for p, r in zip(pat_parts, res_parts))

def authorize(rules, action, resource):
    """Authorize an action on a resource.
    Deny rules take precedence over allow rules.
