import json
from clocks import compare, validate, joined

def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"))

def normalize(record):
    return {
        "key": record["key"],
        "node": record["node"],
        "clock": validate(record.get("clock", {})),
        "value": record.get("value"),
        "deleted": bool(record.get("deleted", False)),
    }

def resolve(records):
    # Deduplicate by canonical representation of the normalized record
    unique = {}
    for r in records:
        rec = normalize(r)
        unique[canonical(rec)] = rec
    versions = list(unique.values())

    # Frontier: versions not strictly dominated by any other version
    frontier = []
    for v in versions:
        dominated = False
        for other in versions:
            if other is v:
                continue
            # other strictly dominates v?
            if compare(other["clock"], v["clock"]) == 1:
                dominated = True
                break
        if not dominated:
            frontier.append(v)

    # Choose winner according to policy:
    # 1. Tombstone (deleted=True) wins over live values
    # 2. Lexicographically greatest node
    # 3. Lexicographically greatest canonical JSON value
    def winner_key(v):
        return (
            v["deleted"],               # True > False
            v["node"],                  # higher string wins
            canonical(v["value"])       # higher string wins
        )
    winner = max(frontier, key=winner_key)

    return {
        "key": winner["key"],
        "value": None if winner["deleted"] else winner["value"],
        "deleted": winner["deleted"],
        "clock": joined([v["clock"] for v in versions]),
        "winner": winner["node"],
        "conflict": len(frontier) > 1,
    }

