    keys = set(left) | set(right)
    greater_all = all(left.get(k, 0) >= right.get(k, 0) for k in keys)
    greater_any = any(left.get(k, 0) > right.get(k, 0) for k in keys)
    smaller_all = all(left.get(k, 0) <= right.get(k, 0) for k in keys)
    smaller_any = any(left.get(k, 0) < right.get(k, 0) for k in keys)
    if greater_all and greater_any:
        return 1
    if smaller_all and smaller_any:
        return -1
    return None

def joined(clocks):
    result = {}
    for clock in clocks:
        for key, value in validate(clock).items():
            result[key] = max(result.get(key, 0), value)
