    left, right = validate(left), validate(right)
    keys = set(left) | set(right)
    left_ge = all(left.get(k, 0) >= right.get(k, 0) for k in keys)
    right_ge = all(right.get(k, 0) >= left.get(k, 0) for k in keys)
    left_gt = any(left.get(k, 0) > right.get(k, 0) for k in keys)
    right_gt = any(right.get(k, 0) > left.get(k, 0) for k in keys)
    if left_ge and left_gt:
        return 1
    if right_ge and right_gt:
        return -1
    return 0

def joined(clocks):
    result = {}
    for clock in clocks:
        for key, value in validate(clock).items():
            result[key] = max(result.get(key, 0), value)
    return dict(sorted(result.items()))

