from indexing import tokens

def ranked(indexed, query, mode, labels):
    """Return ranked search results.

    * ``indexed`` – output of :func:`indexing.index`.
    * ``query`` – raw query string.
    * ``mode`` – ``"all"`` (default) requires every term, ``"any"`` requires at least one.
    * ``labels`` – list of labels that must all be present on a document.
    """
    if mode not in ("all", "any"):
        raise ValueError("unknown query mode")
    # Normalise and deduplicate query terms
    terms = list(dict.fromkeys(tokens(query)))
    if not terms:
        return []
    result = []
    for doc, counts in indexed:
        # Conjunctive label filter: all supplied labels must be present
        doc_labels = set(doc.get("labels", []))
        if labels and not set(labels).issubset(doc_labels):
            continue
        # Determine which terms are present in the document
        hits = [term in counts for term in terms]
        if (mode == "all" and all(hits)) or (mode == "any" and any(hits)):
            # Score is the sum of frequencies for the unique query terms
            score = sum(counts.get(term, 0) for term in terms)
            result.append({"id": doc["id"], "title": doc["title"], "score": score})
    # Sort by descending score then ascending id (lexicographically)
    return sorted(result, key=lambda row: (-row["score"], row["id"]))

def facets(indexed):
    """Return a mapping of label -> document count.

    Each document contributes at most one count per distinct label, even if the
    label appears multiple times in the document's ``labels`` list.
    """
    result = {}
    for doc, _ in indexed:
        # Use a set to avoid double‑counting duplicate labels within the same doc
        for label in set(doc.get("labels", [])):
            result[label] = result.get(label, 0) + 1
    # Return a dict sorted by label for deterministic output
    return dict(sorted(result.items()))

